from fastapi.testclient import TestClient
from app.main import app

def test_mirror_to_dna_compass_and_vault_flow():
    c=TestClient(app);user=c.post('/api/v1/users/demo',json={'display_name':'Test Maya','email':'test-maya@demo.local'}).json();uid=user['id'];interest=c.post(f'/api/v1/mirror/{uid}/interests',json={'category':'game','name':'Angry Birds'}).json();assert interest['purpose']=='entertainment';assert interest['dna_allowed'] is False;assert c.get(f'/api/v1/dna/{uid}/patterns').json()==[];assert c.post(f'/api/v1/dna/{uid}/consent',json={'consent':True}).status_code==200
    for kind,text in [('empty_room','Having control over my choices feels important.'),('future_me','I want freedom to make my own choices.'),('reflection','I feel independent when I choose my own direction.')]:assert c.post(f'/api/v1/dna/{uid}/experiences',json={'experience_type':kind,'input_mode':'text','response':{'reflection':text},'consent_for_analysis':True}).status_code==200
    strands=c.get(f'/api/v1/dna/{uid}/strands').json();assert strands;sid=strands[0]['id'];assert c.patch(f'/api/v1/dna/{uid}/strands/{sid}',json={'user_label':'Having control over my own choices'}).status_code==200;chapter=c.post(f'/api/v1/compass/{uid}/chapters',json={'title':'Placement'}).json();reflection=c.post(f'/api/v1/compass/{uid}/reflect',json={'chapter_id':chapter['id'],'focus':{}}).json();assert reflection['type']=='question';assert 'Having control over my own choices' in reflection['text'];vault=c.get(f'/api/v1/vault/{uid}').json();assert vault['entertainment'][0]['purpose']=='entertainment';assert vault['self_discovery']
